contract InvMutTest {
    C c;
    bool called;
    address lastFrom;
    uint lastTo;
    uint lastV;

    constructor(C _c) { c = _c; }

    function run(address[] memory tos, uint[] memory vs) public {
        require(tos.length == 1 && vs.length == 1);
        bool ok = c.transfer(address(this), tos, vs);
        assert(ok && called && lastFrom == address(this) && lastTo == uint160(tos[0]) && lastV == vs[0]);
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (data.length == 100 && bytes4(data[0:4]) == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            (address from, address to, uint v) = abi.decode(data[4:], (address, address, uint256));
            called = true;
            lastFrom = from;
            lastTo = uint160(to);
            lastV = v;
        }
        return abi.encode(true);
    }

    receive() external payable {}
}

